# ---------------------------------------------------------------------------
# Camera lookup helpers
# ---------------------------------------------------------------------------

def normalize_camera_name(raw_name: str) -> str:
    """Normalize a camera name from FITS header for database lookup."""
    if not raw_name:
        return ''

    name = raw_name.strip()
    name_upper = name.upper()

    # Try direct mapping first
    if name_upper in INSTRUMENT_HEADER_MAPPING:
        return INSTRUMENT_HEADER_MAPPING[name_upper]

    # Try removing common prefixes
    for prefix in ['ZWO ', 'QHY ', 'FLI ', 'SBIG ', 'ATIK ', 'MORAVIAN ',
                   'PLAYER ONE ', 'SVBONY ', 'TOUPTEK ', 'CANON ', 'NIKON ', 'SONY ']:
        if name_upper.startswith(prefix):
            stripped = name[len(prefix):].strip()
            stripped_upper = stripped.upper()
            if stripped_upper in INSTRUMENT_HEADER_MAPPING:
                return INSTRUMENT_HEADER_MAPPING[stripped_upper]
            # Also check direct database key
            if stripped in SENSORS_DATABASE:
                return stripped

    # Try partial match
    for db_key in SENSORS_DATABASE:
        if db_key.upper() in name_upper or name_upper in db_key.upper():
            return db_key

    return name


def lookup_camera(raw_name: str) -> Optional[Dict[str, Any]]:
    """
    Look up camera specs from a FITS header instrument name.
    Returns dict with gain, read_noise, full_well, pixel_size, etc.
    """
    canonical = normalize_camera_name(raw_name)

    if canonical in SENSORS_DATABASE:
        return SENSORS_DATABASE[canonical]

    # Fuzzy: try case-insensitive
    for key, specs in SENSORS_DATABASE.items():
        if key.upper() == canonical.upper():
            return specs

    return None


def get_pixel_size(raw_name: str) -> Optional[float]:
    """Get pixel size in microns for a camera."""
    specs = lookup_camera(raw_name)
    return specs['pixel_size'] if specs else None


def get_sensor_dimensions(raw_name: str) -> Optional[tuple]:
    """Get sensor dimensions (width_px, height_px) for a camera."""
    specs = lookup_camera(raw_name)
    if specs:
        return (specs['width_px'], specs['height_px'])
    return None


def is_color_camera(raw_name: str) -> Optional[bool]:
    """Determine if a camera is color (OSC) based on name patterns."""
    if not raw_name:
        return None
    name = raw_name.upper()
    # Common color indicators
    color_patterns = ['MC', 'OSC', 'COLOR', '-C', ' C ', 'COLOUR']
    mono_patterns = ['MM', 'MONO', '-M ', '-M-']

    for p in mono_patterns:
        if p in name:
            return False
    for p in color_patterns:
        if p in name:
            return True

    # DSLRs/Mirrorless are always color
    dslr_brands = ['CANON', 'NIKON', 'SONY', 'SIGMA', 'PENTAX', 'FUJI']
    if any(b in name for b in dslr_brands):
        return True

    return None


def list_cameras_by_brand() -> Dict[str, list]:
    """Return cameras organized by brand."""
    brands = {}
    for key in sorted(SENSORS_DATABASE.keys()):
        if key == 'default':
            continue

        if key.startswith('ASI'):
            brand = 'ZWO'
        elif key.startswith('QHY'):
            brand = 'QHY'
        elif key.startswith('FLI'):
            brand = 'FLI'
        elif key.startswith('STF') or key.startswith('STT'):
            brand = 'SBIG'
        elif key.startswith('ATIK'):
            brand = 'Atik'
        elif key.startswith('G') and any(c.isdigit() for c in key[:3]):
            brand = 'Moravian'
        elif key.startswith('CANON'):
            brand = 'Canon'
        elif key.startswith('NIKON'):
            brand = 'Nikon'
        elif key.startswith('SONY') or key.startswith('IMX'):
            brand = 'Sony'
        elif key.startswith('PLAYER'):
            brand = 'Player One'
        elif key.startswith('SVBONY'):
            brand = 'SVBONY'
        elif key.startswith('Touptek'):
            brand = 'Touptek'
        elif key.startswith('SIGMA'):
            brand = 'Sigma'
        else:
            brand = 'Other'

        if brand not in brands:
            brands[brand] = []
        brands[brand].append(key)

    return brands
